async(page)=>{
const assert=(v,m)=>{if(!v)throw Error(m)},errors=[],base='E:/Dr.RouteFit/prototype/records/2026-10-24-closure-update/';page.on('pageerror',e=>errors.push(e.message));await page.goto('http://127.0.0.1:4173/prototype/showcase.html');await page.setViewportSize({width:1440,height:1000});await page.locator('[data-action=reset]').click();await page.locator('[value=reset]').click();
const state=()=>page.evaluate(()=>JSON.parse(sessionStorage.getItem('routefit-core-showcase-v1')));
const submit=async(a,p={},confirm=false)=>{const f=page.locator(`[data-command=${a}]`);for(const[k,v]of Object.entries(p))await f.locator(`[name=${k}]`).fill(String(v));if(confirm)await f.locator('[name=confirmed]').check();await f.locator('[type=submit]').click();};
await page.locator('[data-action=preset-normal]').click();await page.locator('[data-select=VAN]').click();await submit('offer',{},true);await submit('accept',{},true);await submit('release',{evidence:'LOAD'},true);await submit('pickup',{count:6,evidence:'PICKUP'});await page.locator('[data-action=depart]').click();await submit('deliver',{count:4,amount:24,evidence:'POD-A'});
await page.locator('[data-tab=exceptions]').click();await submit('issue',{evidence:'CALL-NO-ANSWER'});assert((await state()).issue.custody==='司机','custody lost');await submit('retry',{evidence:'CUSTOMER-CONFIRMED'},true);assert((await state()).stage==='transit','retry failed');await page.locator('[name=reason]').selectOption('refused');await submit('issue',{evidence:'REFUSED'});await page.locator('[data-tab=execution]').click();assert(await page.locator('[data-command=deliver]').count()===0,'exception can deliver');await page.locator('[data-action=exceptions]').click();await submit('authorizeReturn',{evidence:'RETURN-AUTH'},true);await submit('arriveReturn',{evidence:'ARRIVED'});await submit('receiveReturn',{count:1,evidence:'SHORT'});assert((await state()).stage==='returned','short received');await page.reload();await page.locator('[data-tab=exceptions]').click();await submit('receiveReturn',{count:2,evidence:'RETURN-RECEIPT'});assert((await state()).issue.custody==='仓库待检区','quarantine custody');await page.screenshot({path:base+'return-fee-review.png',fullPage:true});await submit('waive',{evidence:'CUSTOMER-OPS-APPROVAL'},true);
await page.locator('[data-tab=finance]').click();assert((await page.locator('#sc-workspace').innerText()).includes('减免 $20.00'),'adjustment missing');await submit('verify',{evidence:'VERIFY-A'},true);await submit('remit',{amount:46,evidence:'WRONG'});assert((await state()).stage==='verified','old full price accepted');await submit('remit',{amount:24,evidence:'REMIT-A'});await submit('reconcile',{amount:24,evidence:'CLOSED'},true);assert((await state()).stage==='closed','not closed');await page.screenshot({path:base+'finance-closed.png',fullPage:true});
await page.locator('[data-tab=control]').click();assert((await page.locator('#sc-workspace').innerText()).includes('已退回待检'),'return mislabeled');assert(await page.locator('#sc-workspace button').count()===0,'control writes');
for(const width of [390,1440]){await page.setViewportSize({width,height:900});for(const tab of ['execution','exceptions','finance','control','roadmap']){await page.locator(`[data-tab=${tab}]`).click();assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'overflow '+tab);}}
await page.setViewportSize({width:390,height:844});await page.locator('[data-tab=exceptions]').click();await page.screenshot({path:base+'return-mobile.png',fullPage:true});assert(!errors.length,errors.join('\n'));return {status:'PASS',checks:['同单异常→恢复→再拒收→授权返仓→点收→费用减免→现金结清','点收差异、旧金额交款阻断；刷新恢复','原报价保留、保险调整独立、退回待检不伪装签收','五个相关页签390/1440无溢出，规划页区分已实现与待做'],pageErrors:errors,finalState:await state()};
}
